import{_ as e,c as i,o as l,aj as t}from"./chunks/framework.B-K7myP5.js";const m=JSON.parse('{"title":"Wails","description":"使用 Go 和 Web 技术构建桌面应用程序。","frontmatter":{"title":"Wails","description":"使用 Go 和 Web 技术构建桌面应用程序。","lastUpdated":"2026-01-28","tags":[],"link":"/awesome/go/wails","tag":"GUI","layout":"doc","sidebar":true,"aside":true},"headers":[],"params":{"pkg":"go/wails","sidebar":[{"text":"GUI","items":[{"text":"Wails","link":"/awesome/go/wails","description":"使用 Go 和 Web 技术构建桌面应用程序。"}]}]},"relativePath":"awesome/go/wails.md","filePath":"awesome/[pkg].md"}'),s={name:"awesome/go/wails.md"};function r(o,a,n,d,p,c){return l(),i("div",null,[...a[0]||(a[0]=[t('<h2 id="项目介绍" tabindex="-1">项目介绍 <a class="header-anchor" href="#项目介绍" aria-label="Permalink to “项目介绍”">​</a></h2><p>为 Go 程序提供 Web 界面的传统方法是通过内置 Web 服务器。Wails 提供了一种不同的方法：它提供了将 Go 代码和 Web 前端一起打包成单个二进制文件的能力。通过提供的工具，可以很轻松的完成项目的创建、编译和打包。你所要做的就是发挥创造力！</p><h2 id="功能" tabindex="-1">功能 <a class="header-anchor" href="#功能" aria-label="Permalink to “功能”">​</a></h2><ul><li>后端使用标准 Go</li><li>使用您已经熟悉的任何前端技术来构建您的 UI</li><li>使用内置模板为您的 Go 程序快速创建丰富的前端</li><li>从 Javascript 轻松调用 Go 方法</li><li>为您的 Go 结构体和方法自动生成 Typescript 声明</li><li>原生对话框和菜单</li><li>支持现代半透明和“磨砂窗”效果</li><li>Go 和 Javascript 之间统一的事件系统</li><li>强大的命令行工具，可快速生成和构建您的项目</li><li>跨平台</li><li>使用原生渲染引擎 - <em>没有嵌入浏览器</em>！</li></ul><h3 id="路线图" tabindex="-1">路线图 <a class="header-anchor" href="#路线图" aria-label="Permalink to “路线图”">​</a></h3><p>项目路线图可在 <a href="https://github.com/wailsapp/wails/discussions/1484" target="_blank" rel="noreferrer">此处</a> 找到。在提出增强请求之前请查阅此内容。</p><h2 id="快速入门" tabindex="-1">快速入门 <a class="header-anchor" href="#快速入门" aria-label="Permalink to “快速入门”">​</a></h2><p>使用说明在 <a href="https://wails.io/zh-Hans/docs/gettingstarted/installation/" target="_blank" rel="noreferrer">官网</a>。</p>',8)])])}const _=e(s,[["render",r]]);export{m as __pageData,_ as default};
